package com.starlight.greetings.application;
import com.starlight.greetings.web.ApiException;
import java.util.Map; import java.util.UUID;
import org.springframework.http.HttpStatus; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class JdbcLetterWriteService implements LetterWriteService { private final JdbcTemplate jdbc; public JdbcLetterWriteService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 @Transactional public String write(Map<String,Object> input){String bridge=(String)input.get("bridgeId"),question=(String)input.get("questionId"),body=(String)input.get("body"),user=(String)input.get("userId"),nickname=(String)input.get("nickname");int theme=input.get("theme") instanceof Number n?n.intValue():0;if(body==null||body.codePointCount(0,body.length())>150)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_BODY","편지는 150자 이내로 입력해 주세요.");if(theme<1||theme>4)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_THEME","유리병 테마를 다시 선택해 주세요.");var questions=jdbc.query("select id from questions where bridge_id=? and status='published' and effective_at<=now() order by effective_at desc,id desc limit 1",(r,i)->r.getString(1),bridge);if(questions.isEmpty()||!questions.get(0).equals(question))throw new ApiException(HttpStatus.CONFLICT,"QUESTION_CHANGED","질문이 바뀌었어요. 새 질문을 확인해 주세요.");String id=UUID.randomUUID().toString();jdbc.update("insert into letters (id,bridge_id,question_id,author_user_id,display_nickname,body,theme,is_seed,status) values (?,?,?,?,?,?,?,false,'published')",id,bridge,question,user,nickname,body,theme);return id;}}
